package vn.cineman.service;
import java.util.*;import java.net.*;import java.nio.charset.StandardCharsets;import javax.crypto.*;import javax.crypto.spec.SecretKeySpec;import java.security.*;import java.time.*;import java.time.format.*;import java.math.*;
public final class Vnpay8 {
 public static String config(String key){return System.getenv().getOrDefault(key,"");}
 public static boolean ready(){return !config("VNPAY_TMN_CODE").isBlank()&&!config("VNPAY_HASH_SECRET").isBlank()&&!config("VNPAY_RETURN_URL").isBlank();}
 public static String canonical(Map<String,String> params){return new TreeMap<>(params).entrySet().stream().filter(e->e.getKey().startsWith("vnp_")&&!Set.of("vnp_SecureHash","vnp_SecureHashType").contains(e.getKey())&&e.getValue()!=null&&!e.getValue().isEmpty()).map(e->encode(e.getKey())+"="+encode(e.getValue())).collect(java.util.stream.Collectors.joining("&"));}
 private static String encode(String s){return URLEncoder.encode(s,StandardCharsets.US_ASCII);}
 public static String sign(Map<String,String> params,String secret){try{Mac mac=Mac.getInstance("HmacSHA512");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA512"));return HexFormat.of().formatHex(mac.doFinal(canonical(params).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 public static boolean valid(Map<String,String> p){if(!ready()||!config("VNPAY_TMN_CODE").equals(p.get("vnp_TmnCode")))return false;return MessageDigest.isEqual(sign(p,config("VNPAY_HASH_SECRET")).getBytes(StandardCharsets.US_ASCII),p.getOrDefault("vnp_SecureHash","").toLowerCase(Locale.ROOT).getBytes(StandardCharsets.US_ASCII));}
 public static String url(long id,BigDecimal amount,String ip,LocalDateTime expires){if(!ready())throw new IllegalArgumentException("VNPAY sandbox chưa được cấu hình. Chưa tạo giao dịch thanh toán.");var p=new TreeMap<String,String>();var fmt=DateTimeFormatter.ofPattern("yyyyMMddHHmmss");p.put("vnp_Version","2.1.0");p.put("vnp_Command","pay");p.put("vnp_TmnCode",config("VNPAY_TMN_CODE"));p.put("vnp_Amount",amount.multiply(BigDecimal.valueOf(100)).toBigIntegerExact().toString());p.put("vnp_CurrCode","VND");p.put("vnp_TxnRef",Long.toString(id));p.put("vnp_OrderInfo","Thanh toan ve CineMan "+id);p.put("vnp_OrderType","other");p.put("vnp_Locale","vn");p.put("vnp_ReturnUrl",config("VNPAY_RETURN_URL"));p.put("vnp_IpAddr",ip);p.put("vnp_CreateDate",LocalDateTime.now(ZoneId.of("Asia/Ho_Chi_Minh")).format(fmt));p.put("vnp_ExpireDate",expires.format(fmt));return "https://sandbox.vnpayment.vn/paymentv2/vpcpay.html?"+canonical(p)+"&vnp_SecureHash="+sign(p,config("VNPAY_HASH_SECRET"));}
}
